SELECT COUNT(*) AS active_products FROM products WHERE status='ACTIVE' AND deleted_at IS NULL;
SELECT c.name AS category,COUNT(*) AS products FROM products p JOIN categories c ON c.id=p.category_id WHERE p.status='ACTIVE' AND p.deleted_at IS NULL GROUP BY c.name ORDER BY c.name;
